CREATE POLICY retained_document_source_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='sales-receipt-intake' AND EXISTS(SELECT 1 FROM public.document_read_jobs j WHERE j.source_path=name AND j.uploaded_by=auth.uid() AND public.user_has_tenant(auth.uid(),j.tenant_id)));
CREATE TABLE public.document_source_archives(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),source_record_id uuid NOT NULL,source_snapshot jsonb NOT NULL,intake_id uuid NOT NULL REFERENCES public.sales_receipt_intakes(id),operation_id uuid NOT NULL REFERENCES public.finance_source_operations(id),actor_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(source_record_id));
GRANT SELECT ON public.document_source_archives TO authenticated;GRANT ALL ON public.document_source_archives TO service_role;ALTER TABLE public.document_source_archives ENABLE ROW LEVEL SECURITY;CREATE POLICY source_archives_read ON public.document_source_archives FOR SELECT TO authenticated USING(actor_id=auth.uid() AND public.user_has_tenant(auth.uid(),tenant_id));
CREATE FUNCTION public.document_undo_receipt(p_record uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.sales_records%ROWTYPE;i public.sales_receipt_intakes%ROWTYPE;j uuid;op uuid;BEGIN
SELECT * INTO s FROM public.sales_records WHERE id=p_record FOR UPDATE;IF NOT FOUND OR NOT public.user_has_tenant(auth.uid(),s.tenant_id) OR NOT(public.has_role(auth.uid(),'admin') OR public.is_tenant_admin(s.tenant_id,auth.uid())) OR NOT public.user_has_venue(auth.uid(),s.venue_id) THEN RAISE EXCEPTION 'Receipt Undo access required';END IF;
SELECT * INTO i FROM public.sales_receipt_intakes WHERE posted_record_id=s.id AND tenant_id=s.tenant_id AND status='posted' FOR UPDATE;IF NOT FOUND OR i.uploaded_by<>auth.uid() THEN RAISE EXCEPTION 'Only your automatically posted receipt can be undone';END IF;
IF EXISTS(SELECT 1 FROM public.sales_records WHERE tenant_id=s.tenant_id AND date=s.date AND venue=s.venue AND id<>s.id) THEN RAISE EXCEPTION 'Other reports share this posting; source-group review required';END IF;
IF s.event_id IS NOT NULL OR EXISTS(SELECT 1 FROM public.sales_record_notes WHERE sales_record_id=s.id) THEN RAISE EXCEPTION 'Receipt has dependent records; review before Undo';END IF;
SELECT current_entry_id INTO j FROM public.finance_source_postings WHERE tenant_id=s.tenant_id AND source_type='sales_summary' AND source_key=s.date||'__'||s.venue FOR UPDATE;
IF j IS NULL THEN RAISE EXCEPTION 'Live source posting unavailable';END IF;
op:=public.finance_source_date_correct(j,NULL,'Undo · automatically read receipt',public.finance_source_snapshot(j),true);
INSERT INTO public.document_source_archives(tenant_id,source_record_id,source_snapshot,intake_id,operation_id,actor_id) VALUES(s.tenant_id,s.id,to_jsonb(s),i.id,op,auth.uid());UPDATE public.sales_receipt_intakes SET status='resolved',posted_record_id=NULL,reasons='["Undone; original document retained"]' WHERE id=i.id;DELETE FROM public.sales_records WHERE id=s.id;RETURN op;END $$;
REVOKE ALL ON FUNCTION public.document_undo_receipt(uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.document_undo_receipt(uuid) TO authenticated;